'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const out=path.resolve(__dirname,'../outputs/youth-20years-20261011'),s=JSON.parse(fs.readFileSync(path.join(out,'summary.json'),'utf8'));
assert(s.complete||process.argv.includes('--partial'),'Cannot present an incomplete audit as completed.');
// Public projection: relative aggregate comparisons; no individual abilities, talent or caps.
const publicSeries=rows=>rows.map(r=>Object.fromEntries(['season','rosterChangePct','startingChangePct','rosterRangePct','meanAge','youthSharePct'].filter(k=>k in r).map(k=>[k,Array.isArray(r[k])?r[k].map(v=>Number(v.toFixed(3))):Number(r[k].toFixed(3))])));
const data={complete:s.complete,latest:s.latestCommonSeason,fixtures:s.fixtures,cohort:s.cohortSummary,totalSeries:publicSeries(s.totalSeries),countries:s.countries.map(c=>({country:c.country,label:c.label,series:publicSeries(c.series)})),baseline:s.baseline.map(c=>({label:c.label,juvenileGapPct:c.juvenileGapPct})),matured:s.matured.map(c=>({country:c.country,n:c.n,meanGrowthPct:c.meanGrowthPct,relativePrimeStartPct:c.relativePrimeStartPct}))};
const html=`<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;font-family:var(--font-sans,system-ui);color:var(--foreground,#172033);line-height:1.5}h2{font-size:24px;margin:0 0 8px}h3{font-size:18px;margin:24px 0 10px}p{margin:6px 0 14px}.muted,small{color:var(--muted-foreground,#667085)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.stat{padding:16px;background:var(--secondary,#edf1f7);border-radius:var(--radius,10px)}.stat b{font-size:25px;display:block}.stat span{font-size:12px}select{font:inherit;background:var(--card,#fff);color:inherit;border:1px solid var(--border,#ccd2de);border-radius:7px;padding:8px;max-width:100%}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:16px 0 8px}.chart{width:100%;height:250px;display:block}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px}.key{display:inline-block;width:14px;height:3px;vertical-align:middle;margin-right:5px;background:var(--chart-1,#2671dc)}.key.second{background:var(--chart-2,#9b58c6)}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:right;padding:10px 7px;border-bottom:1px solid var(--border,#d7dde7);white-space:nowrap}th:first-child,td:first-child{text-align:left}th{font-weight:600;color:var(--muted-foreground,#667085)}button{font:inherit;color:inherit;background:none;border:0;cursor:pointer;text-align:left;padding:0;text-decoration:underline;text-underline-offset:3px}.selected{background:var(--accent-surface,#eaf3ff)}.note{font-size:12px;margin-top:12px}.barrow{display:grid;grid-template-columns:110px 1fr 56px;gap:9px;align-items:center;font-size:12px;margin:8px 0}.track{height:8px;background:var(--secondary,#edf1f7);border-radius:8px;overflow:hidden}.fill{height:100%;background:var(--chart-3,#dc9051)}@media(max-width:440px){.stats{gap:7px}.stat{padding:16px}.stat b{font-size:19px}.stat span{font-size:11px}h2{font-size:21px}.barrow{grid-template-columns:90px 1fr 48px}}
</style><h2>Kader und Nachwuchs über 20 Saisons</h2><p class="muted" id="intro"></p><div class="stats"><div class="stat"><b id="roster"></b><span>Kaderqualität gegenüber Start</span></div><div class="stat"><b id="starting"></b><span>Standardaufstellung gegenüber Start</span></div><div class="stat"><b id="fixtures"></b><span>native kompakte Partien</span></div></div>
<div class="controls"><label>Liga <select id="country"><option value="all">Alle Ligavereine</option></select></label></div><svg id="plot" class="chart" viewBox="0 0 680 250" role="img" aria-label="Relative Kaderentwicklung gegenüber dem ursprünglichen Start"></svg><div class="legend"><span><i class="key"></i>Gesamter Kader</span><span><i class="key second"></i>Einheitliche KI-Aufstellung</span><span class="muted">Start = 0 % · Fläche: Spannweite der drei Welten</span></div>
<h3>Unterschiede zwischen den Ligen</h3><div class="controls"><label>Saison <select id="year"></select></label></div><div class="scroll"><table><thead><tr><th>Land</th><th>Kader</th><th>Aufstellung</th><th>Nachwuchsanteil</th><th>Ø Alter</th></tr></thead><tbody id="countries"></tbody></table></div>
<h3>Mit 17 gegenüber den ursprünglichen Profis</h3><p class="muted">Generierung in zwölf zusätzlichen Startwelten. Unterschied der mittleren Positionsqualität, ohne Form oder Frische.</p><div id="birth"></div>
<h3>Was erreichen Jugendspieler bis 24?</h3><p class="muted">Frühe Jahrgänge, die bis 24 im aktiven Spielerbestand bleiben. Ausgeschiedene Kandidaten zählen nicht als entwickelte Profis.</p><p class="note muted" id="cohortnote"></p><div class="scroll"><table><thead><tr><th>Akademieland</th><th>Beobachtet</th><th>Zuwachs</th><th>Gegenüber Startprofis¹</th></tr></thead><tbody id="mature"></tbody></table></div>
<p class="note muted">¹ Positionsbereinigter Vergleich mit ursprünglichen 24–29-jährigen Profis derselben Welt. Der Zuwachs ist ein relativer Durchschnitt; die Auswahl überlebender Spieler begünstigt erfolgreiche Kandidaten. Länder beziehen sich auf Liga/Akademiestandort, nicht auf Spieler-Nationalität. Die Zahlen zeigen Veränderungen eines aggregierten Qualitätsmaßes, keine Tor- oder Siegprognose. Reine Pokalvereine und der gesteuerte Verein Innsbruck Sport sind getrennt von den Ligavereinswerten.</p>
<script>const d=${JSON.stringify(data).replace(/</g,'\\u003c')};const pct=x=>x==null?'–':(x>0?'+':'')+x.toFixed(1).replace('.',',')+' %',number=x=>x.toLocaleString('de-DE');const last=d.totalSeries.at(-1);document.querySelector('#intro').textContent=d.complete?'Drei unabhängige Welten · 95 KI-Ligavereine je Welt · 20 vollständige Saisons':'Zwischenstand: '+d.latest+' Saisons in drei Welten; der 20-Saisons-Test läuft noch.';document.querySelector('#roster').textContent=pct(last.rosterChangePct);document.querySelector('#starting').textContent=pct(last.startingChangePct);document.querySelector('#fixtures').textContent=number(d.fixtures);
document.querySelector('#cohortnote').textContent=d.complete?number(d.cohort.n)+' von '+number(d.cohort.eligibleBorn)+' frühen Kandidaten wurden bis 24 beobachtet ('+(100*d.cohort.n/d.cohort.eligibleBorn).toFixed(1).replace('.',',')+' %). Schon bei Erzeugung lag diese verbleibende Gruppe '+pct(d.cohort.selectedBirthGapPct)+' über allen Kandidaten dieser Jahrgänge.':'';const country=document.querySelector('#country'),year=document.querySelector('#year');d.countries.forEach(c=>country.add(new Option(c.label,c.country)));[0,5,10,15,20].filter(y=>y<=d.latest).concat([d.latest]).filter((v,i,a)=>a.indexOf(v)===i).forEach(y=>year.add(new Option(y===0?'Ursprünglicher Start':'Saison '+y,y)));year.value=d.latest;
function renderPlot(){const s=country.value==='all'?d.totalSeries:d.countries.find(c=>c.country===country.value).series,values=s.flatMap(r=>[r.rosterChangePct,r.startingChangePct,...r.rosterRangePct]),lo=Math.floor(Math.min(-1,...values)/5)*5,hi=Math.ceil(Math.max(1,...values)/5)*5,w=Math.max(300,Math.round(document.querySelector('#plot').getBoundingClientRect().width)),right=w-16,x=y=>48+y/Math.max(20,d.latest)*(right-48),y=v=>210-(v-lo)/(hi-lo)*180;const path=(field)=>s.map((r,i)=>(i?'L':'M')+x(r.season).toFixed(2)+','+y(r[field]).toFixed(2)).join(' '),range=s.map(r=>x(r.season)+','+y(r.rosterRangePct[0])).concat([...s].reverse().map(r=>x(r.season)+','+y(r.rosterRangePct[1]))).join(' ');document.querySelector('#plot').setAttribute('viewBox','0 0 '+w+' 250');let html='';for(let v=lo;v<=hi;v+=5)html+='<line x1="48" y1="'+y(v)+'" x2="'+right+'" y2="'+y(v)+'" stroke="var(--border,#ddd)"/><text x="40" y="'+(y(v)+4)+'" text-anchor="end" font-size="11" fill="var(--muted-foreground,#667085)">'+v+' %</text>';for(const z of [0,5,10,15,20])html+='<text x="'+x(z)+'" y="239" text-anchor="middle" font-size="11" fill="var(--muted-foreground,#667085)">'+z+'</text>';html+='<polygon points="'+range+'" fill="var(--chart-1,#2671dc)" opacity=".12"/><path d="'+path('rosterChangePct')+'" fill="none" stroke="var(--chart-1,#2671dc)" stroke-width="3"/><path d="'+path('startingChangePct')+'" fill="none" stroke="var(--chart-2,#9b58c6)" stroke-width="2.5"/>';document.querySelector('#plot').innerHTML=html;}
function renderTable(){document.querySelector('#countries').innerHTML=d.countries.map(c=>{const r=c.series[Number(year.value)];return'<tr class="'+(country.value===c.country?'selected':'')+'"><td><button data-country="'+c.country+'">'+c.label+'</button></td><td title="Spannweite '+pct(r.rosterRangePct[0])+' bis '+pct(r.rosterRangePct[1])+'">'+pct(r.rosterChangePct)+'</td><td>'+pct(r.startingChangePct)+'</td><td>'+r.youthSharePct.toFixed(1).replace('.',',')+' %</td><td>'+r.meanAge.toFixed(1).replace('.',',')+'</td></tr>';}).join('');}
document.querySelector('#birth').innerHTML=d.baseline.map(c=>'<div class="barrow"><span>'+c.label+'</span><div class="track"><div class="fill" style="width:'+Math.min(100,-c.juvenileGapPct/30*100)+'%"></div></div><span>'+pct(c.juvenileGapPct)+'</span></div>').join('');document.querySelector('#mature').innerHTML=d.matured.map(c=>'<tr><td>'+d.countries.find(r=>r.country===c.country).label+'</td><td>'+number(c.n)+'</td><td>'+pct(c.meanGrowthPct)+'</td><td>'+pct(c.relativePrimeStartPct)+'</td></tr>').join('');country.onchange=()=>{renderPlot();renderTable()};year.onchange=renderTable;document.querySelector('#countries').onclick=e=>{const b=e.target.closest('button[data-country]');if(b){country.value=b.dataset.country;renderPlot();renderTable();}};window.onresize=renderPlot;renderPlot();renderTable();console.log(JSON.stringify({countries:d.countries.length,lastSeason:d.latest,complete:d.complete,nonfinite:d.totalSeries.some(r=>!Number.isFinite(r.rosterChangePct))}));</script></html>`;
fs.writeFileSync(path.join(out,'report.html'),html);console.log(path.join(out,'report.html'));
